      c: "#include <stdio.h>\nint main() {\n    int n; if(scanf(\"%d\", &n) != EOF) {\n        int a[100001]; for(int i=0; i<n; i++) scanf(\"%d\", &a[i]);\n        int t; scanf(\"%d\", &t); int l=0, r=n-1, ans=-1;\n        while(l<=r) { int m=l+(r-l)/2; if(a[m]==t) { ans=m; break; } else if(a[m]<t) l=m+1; else r=m-1; }\n        printf(\"%d\\n\", ans);\n    } return 0;\n}",
      csharp: "using System;\nclass Program {\n    static void Main() {\n        string s = Console.ReadLine(); if(s==null) return;\n        int n = int.Parse(s); int[] a = Console.ReadLine().Split(' ', StringSplitOptions.RemoveEmptyEntries).Select(int.Parse).ToArray();\n        int t = int.Parse(Console.ReadLine()); int l=0, r=n-1, ans=-1;\n        while(l<=r) { int m=l+(r-l)/2; if(a[m]==t) { ans=m; break; } else if(a[m]<t) l=m+1; else r=m-1; }\n        Console.WriteLine(ans);\n    }\n}",
