      java: "import java.util.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if(sc.hasNext()) {\n            String s = sc.next(); HashMap<Character, Integer> m = new HashMap<>();\n            int start = 0, mx = 0;\n            for(int i=0; i<s.length(); i++) {\n                char c = s.charAt(i);\n                if(m.containsKey(c)) start = Math.max(start, m.get(c)+1);\n                m.put(c, i); mx = Math.max(mx, i - start + 1);\n            }\n            System.out.println(mx);\n        }\n    }\n}",
