      csharp: "using System;\nusing System.Collections.Generic;\nclass Program {\n    static void Main() {\n        string s = Console.ReadLine(); if(s==null) return;\n        s = s.Trim(); Dictionary<char, int> m = new Dictionary<char, int>();\n        int start = 0, mx = 0; for(int i=0; i<s.Length; i++) {\n            if(m.ContainsKey(s[i])) start = Math.Max(start, m[s[i]]+1);\n            m[s[i]] = i; mx = Math.Max(mx, i - start + 1);\n        }\n        Console.WriteLine(mx);\n    }\n}",
      go: "package main\nimport \"fmt\"\nfunc main() {\n    var s string; fmt.Scan(&s)\n    m := make(map[rune]int); start, mx := 0, 0\n    for i, c := range s {\n        if j, ok := m[c]; ok && j >= start { start = j + 1 }\n        m[c] = i; if i - start + 1 > mx { mx = i - start + 1 }\n    }\n    fmt.Println(mx)\n}",
      rust: "use std::io::{self, BufRead};\nuse std::collections::HashMap;\nfn main() {\n    let mut line = String::new(); io::stdin().lock().read_line(&mut line).unwrap();\n    let s = line.trim(); let mut m = HashMap::new();\n    let (mut start, mut mx) = (0, 0);\n    for (i, c) in s.chars().enumerate() {\n        if let Some(&j) = m.get(&c) { if j >= start { start = j + 1; } }\n        m.insert(c, i); mx = mx.max(i - start + 1);\n    }\n    println!(\"{}\", mx);\n}"
