      c: "#include <stdio.h>\n#include <stdbool.h>\nint main() {\n    int n; if(scanf(\"%d\", &n) != EOF) {\n        int g[101][101]; for(int i=0; i<n; i++) for(int j=0; j<n; j++) scanf(\"%d\", &g[i][j]);\n        if(g[0][0]==1) { printf(\"NO\\n\"); return 0; }\n        int q[10001][2], head=0, tail=0; q[tail][0]=0; q[tail++][1]=0;\n        bool vis[101][101]={false}; vis[0][0]=true;\n        bool ok = false;\n        while(head<tail) {\n            int r=q[head][0], c=q[head++][1]; if(r==n-1 && c==n-1) { ok=true; break; }\n            int dr[]={0,0,1,-1}, dc[]={1,-1,0,0};\n            for(int i=0; i<4; i++) {\n                int nr=r+dr[i], nc=c+dc[i];\n                if(nr>=0 && nr<n && nc>=0 && nc<n && g[nr][nc]==0 && !vis[nr][nc]) { vis[nr][nc]=true; q[tail][0]=nr; q[tail++][1]=nc; }\n            }\n        }\n        printf(\"%s\\n\", ok ? \"YES\":\"NO\");\n    } return 0;\n}",
