      rust: "use std::io::{self, BufRead};\nuse std::collections::VecDeque;\nfn main() {\n    let stdin = io::stdin(); let mut lines = stdin.lock().lines();\n    if let Some(Ok(l1)) = lines.next() {\n        let n: usize = l1.trim().parse().unwrap();\n        let mut g = Vec::new(); for _ in 0..n { if let Some(Ok(ln)) = lines.next() {\n            let row: Vec<i32> = ln.split_whitespace().map(|x| x.parse().unwrap()).collect(); g.push(row);\n        } }\n        if g[0][0] == 1 { println!(\"NO\"); return; }\n        let mut q = VecDeque::new(); q.push_back((0,0));\n        let mut vis = vec![vec![false; n]; n]; vis[0][0] = true; let mut ok = false;\n        while let Some((r, c)) = q.pop_front() {\n            if r == n-1 && c == n-1 { ok = true; break; }\n            for (dr, dc) in &[(0,1),(0,-1),(1,0),(-1,0)] {\n                let nr = r as i32 + dr; let nc = c as i32 + dc;\n                if nr>=0 && nr<n as i32 && nc>=0 && nc<n as i32 {\n                    let (nr, nc) = (nr as usize, nc as usize);\n                    if g[nr][nc] == 0 && !vis[nr][nc] { vis[nr][nc] = true; q.push_back((nr, nc)); }\n                }\n            }\n        }\n        println!(\"{}\", if ok { \"YES\" } else { \"NO\" });\n    }\n}"
