      java: "import java.util.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if(sc.hasNextInt()) {\n            int n = sc.nextInt(); int[][] g = new int[n][n];\n            for(int i=0; i<n; i++) for(int j=0; j<n; j++) g[i][j] = sc.nextInt();\n            if(g[0][0]==1) { System.out.println(-1); return; }\n            Queue<int[]> q = new LinkedList<>(); q.add(new int[]{0,0,1});\n            boolean[][] vis = new boolean[n][n]; vis[0][0]=true;\n            while(!q.isEmpty()) {\n                int[] cur = q.poll(); if(cur[0]==n-1 && cur[1]==n-1) { System.out.println(cur[2]); return; }\n                int[] dr={0,0,1,-1}, dc={1,-1,0,0};\n                for(int i=0; i<4; i++) {\n                    int nr=cur[0]+dr[i], nc=cur[1]+dc[i];\n                    if(nr>=0 && nr<n && nc>=0 && nc<n && g[nr][nc]==0 && !vis[nr][nc]) { vis[nr][nc]=true; q.add(new int[]{nr, nc, cur[2]+1}); }\n                }\n            }\n            System.out.println(-1);\n        }\n    }\n}",
