      c: "#include <stdio.h>\n#include <stdbool.h>\nint main() {\n    int n; if(scanf(\"%d\", &n) != EOF) {\n        int g[101][101]; for(int i=0; i<n; i++) for(int j=0; j<n; j++) scanf(\"%d\", &g[i][j]);\n        if(g[0][0]==1) { printf(\"-1\\n\"); return 0; }\n        int q[10001][3], head=0, tail=0; q[tail][0]=0; q[tail][1]=0; q[tail++][2]=1;\n        bool vis[101][101]={false}; vis[0][0]=true;\n        while(head<tail) {\n            int r=q[head][0], c=q[head][1], d=q[head++][2]; if(r==n-1 && c==n-1) { printf(\"%d\\n\", d); return 0; }\n            int dr[]={0,0,1,-1}, dc[]={1,-1,0,0};\n            for(int i=0; i<4; i++) {\n                int nr=r+dr[i], nc=c+dc[i];\n                if(nr>=0 && nr<n && nc>=0 && nc<n && g[nr][nc]==0 && !vis[nr][nc]) { vis[nr][nc]=true; q[tail][0]=nr; q[tail][1]=nc; q[tail++][2]=d+1; }\n            }\n        }\n        printf(\"-1\\n\");\n    } return 0;\n}",
      csharp: "using System;\nusing System.Collections.Generic;\nclass Program {\n    static void Main() {\n        string l = Console.ReadLine(); if(l==null) return;\n        int n = int.Parse(l); int[,] g = new int[n,n];\n        for(int i=0; i<n; i++) {\n            string[] line = Console.ReadLine().Split(' ', StringSplitOptions.RemoveEmptyEntries);\n            for(int j=0; j<n; j++) g[i,j] = int.Parse(line[j]);\n        }\n        if(g[0,0]==1) { Console.WriteLine(-1); return; }\n        Queue<int[]> q = new Queue<int[]>(); q.Enqueue(new int[]{0,0,1});\n        bool[,] vis = new bool[n,n]; vis[0,0]=true;\n        while(q.Count > 0) {\n            int[] cur = q.Dequeue(); if(cur[0]==n-1 && cur[1]==n-1) { Console.WriteLine(cur[2]); return; }\n            int[] dr={0,0,1,-1}, dc={1,-1,0,0};\n            for(int i=0; i<4; i++) {\n                int nr=cur[0]+dr[i], nc=cur[1]+dc[i];\n                if(nr>=0 && nr<n && nc>=0 && nc<n && g[nr,nc]==0 && !vis[nr,nc]) { vis[nr,nc]=true; q.Enqueue(new int[]{nr, nc, cur[2]+1}); }\n            }\n        }\n        Console.WriteLine(-1);\n    }\n}",
